package com.tietsync.academic;
import com.tietsync.security.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import jakarta.validation.constraints.*; import java.util.*; import java.time.*; import java.util.stream.*;
@RestController @RequestMapping("/api/v1") @Validated class ApiController { final UserRepository users;final ClassroomRepository classrooms;final AssignmentRepository assignments;final AttendanceRepository attendance;final EventRepository events;final ResourceRepository resources;final SlotRepository slots;final ConsultationRepository consultations;final ScheduleRepository schedules;final AcademicService service;final JwtService jwt;
 ApiController(UserRepository u,ClassroomRepository c,AssignmentRepository a,AttendanceRepository at,EventRepository e,ResourceRepository re,SlotRepository sl,ConsultationRepository co,ScheduleRepository sc,AcademicService sv,JwtService j){users=u;classrooms=c;assignments=a;attendance=at;events=e;resources=re;slots=sl;consultations=co;schedules=sc;service=sv;jwt=j;}
 record AuthRequest(@NotBlank @Email String email,@NotBlank String password){} record Signup(@NotBlank String fullName,@NotBlank @Email String email,@Size(min=8) String password,@NotBlank String role,String rollNumber,String facultyId,String branch,Integer batchYear,String designation,String cabinLocation,String department){} record AuthResponse(String token,Map<String,Object> user){}
 @PostMapping("/auth/login") AuthResponse login(@RequestBody @Validated AuthRequest r){UserAccount u=users.findByEmailIgnoreCase(r.email).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!service.encoder.matches(r.password,u.passwordHash)||!u.approved)throw new IllegalArgumentException("Invalid email or password, or faculty account awaits approval");return auth(u);}
 @PostMapping("/auth/register") ResponseEntity<AuthResponse> register(@RequestBody @Validated Signup r){if(users.findByEmailIgnoreCase(r.email).isPresent())throw new IllegalArgumentException("An account with this email already exists");Role role="FACULTY".equalsIgnoreCase(r.role)?Role.FACULTY:Role.STUDENT;if(role==Role.STUDENT&&!r.email.toLowerCase().endsWith("@thapar.edu"))throw new IllegalArgumentException("Student email must use @thapar.edu");UserAccount u=new UserAccount();u.email=r.email.toLowerCase();u.passwordHash=service.encoder.encode(r.password);u.fullName=r.fullName;u.role=role;u.rollNumber=r.rollNumber;u.facultyId=r.facultyId;u.branch=r.branch;u.batchYear=r.batchYear;u.designation=r.designation;u.cabinLocation=r.cabinLocation;u.department=r.department;u.approved=role==Role.STUDENT;users.save(u);return ResponseEntity.status(201).body(role==Role.FACULTY?new AuthResponse(null,userDto(u)):auth(u));}
 private AuthResponse auth(UserAccount u){return new AuthResponse(jwt.create(u.id,u.role.name()),userDto(u));} private Map<String,Object> userDto(UserAccount u){return Map.of("id",u.id,"fullName",u.fullName,"email",u.email,"role",u.role,"rollNumber",Objects.toString(u.rollNumber,""),"facultyId",Objects.toString(u.facultyId,""),"branch",Objects.toString(u.branch,""),"department",Objects.toString(u.department,""),"cabinLocation",Objects.toString(u.cabinLocation,""));}
 private UUID me(Authentication a){return UUID.fromString((String)a.getPrincipal());}
 @GetMapping("/classrooms") List<Map<String,Object>> rooms(@RequestParam(defaultValue="")String q){return (q.isBlank()?classrooms.findAll():classrooms.findByCodeContainingIgnoreCaseOrNameContainingIgnoreCase(q,q)).stream().map(x->Map.<String,Object>of("id",x.id,"code",x.code,"name",x.name,"building",x.building,"floor",x.floor,"capacity",x.capacity,"amenities",x.amenities,"directions",x.directions,"description",x.description,"demonstrationData",x.demonstrationData)).toList();}
 @GetMapping("/faculty") List<Map<String,Object>> faculty(@RequestParam(defaultValue="")String q){return users.findByRole(Role.FACULTY).stream().filter(x->q.isBlank()||x.fullName.toLowerCase().contains(q.toLowerCase())||Objects.toString(x.department,"").toLowerCase().contains(q.toLowerCase())).map(this::userDto).toList();}
 @GetMapping("/faculty/{id}/slots") List<Map<String,Object>> facultySlots(@PathVariable UUID id){return slots.findByFacultyIdAndAvailableTrue(id).stream().map(s->Map.<String,Object>of("id",s.id,"date",s.slotDate,"startTime",s.startTime,"endTime",s.endTime)).toList();}
 @GetMapping("/assignments") List<Map<String,Object>> myAssignments(Authentication a){return assignments.findByOwnerIdOrderByDueDateAsc(me(a)).stream().map(x->Map.<String,Object>of("id",x.id,"title",x.title,"category",x.category,"dueDate",x.dueDate,"completed",x.completed)).toList();}
 record AssignmentInput(@NotBlank String title,@NotBlank String category,LocalDate dueDate){} @PostMapping("/assignments") Map<String,Object> addAssignment(Authentication a,@RequestBody @Validated AssignmentInput i){Assignment x=new Assignment();x.owner=service.user(me(a));x.title=i.title;x.category=i.category;x.dueDate=i.dueDate;assignments.save(x);return Map.of("id",x.id,"title",x.title,"category",x.category,"dueDate",x.dueDate,"completed",x.completed);}
 @PatchMapping("/assignments/{id}/complete") void complete(Authentication a,@PathVariable UUID id){Assignment x=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));if(!x.owner.id.equals(me(a)))throw new IllegalArgumentException("Not your assignment");x.completed=!x.completed;assignments.save(x);} @DeleteMapping("/assignments/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(Authentication a,@PathVariable UUID id){Assignment x=assignments.findById(id).orElseThrow(()->new IllegalArgumentException("Assignment not found"));if(!x.owner.id.equals(me(a)))throw new IllegalArgumentException("Not your assignment");assignments.delete(x);}
 @GetMapping("/attendance") List<Map<String,Object>> attendance(Authentication a){return attendance.findByStudentId(me(a)).stream().map(this::attendanceDto).toList();}
 @GetMapping("/calendar") List<Map<String,Object>> calendar(){return events.findAllByOrderByEventDateAsc().stream().map(this::eventDto).toList();} @GetMapping("/resources") List<Map<String,Object>> resourceList(@RequestParam(defaultValue="")String q){return (q.isBlank()?resources.findAll():resources.findBySubjectContainingIgnoreCaseOrTitleContainingIgnoreCase(q,q)).stream().map(this::resourceDto).toList();}
 @GetMapping("/dashboard") Map<String,Object> dashboard(Authentication a){UUID id=me(a);return Map.of("user",userDto(service.user(id)),"assignments",assignments.findByOwnerIdOrderByDueDateAsc(id).stream().limit(5).map(this::assignmentDto).toList(),"attendance",attendance.findByStudentId(id).stream().map(this::attendanceDto).toList(),"schedule",schedules.findByOwnerId(id).stream().map(this::scheduleDto).toList(),"events",events.findAllByOrderByEventDateAsc().stream().limit(5).map(this::eventDto).toList());}
 record SlotInput(LocalDate date,LocalTime startTime,LocalTime endTime){} @PostMapping("/consultations/slots") Map<String,Object> addSlot(Authentication a,@RequestBody SlotInput i){UserAccount f=service.user(me(a));if(f.role!=Role.FACULTY)throw new IllegalArgumentException("Faculty only");ConsultationSlot s=new ConsultationSlot();s.faculty=f;s.slotDate=i.date;s.startTime=i.startTime;s.endTime=i.endTime;slots.save(s);return Map.of("id",s.id);}
 record Booking(UUID slotId,@NotBlank String description){} @PostMapping("/consultations") Map<String,Object> book(Authentication a,@RequestBody @Validated Booking i){ConsultationRequest r=service.book(me(a),i.slotId,i.description);return requestDto(r);}
 @GetMapping("/consultations") List<Map<String,Object>> requests(Authentication a){UserAccount u=service.user(me(a));List<ConsultationRequest> r=u.role==Role.FACULTY?consultations.findByFacultyIdOrderByCreatedAtDesc(u.id):consultations.findByStudentIdOrderByCreatedAtDesc(u.id);return r.stream().map(this::requestDto).toList();} record Decision(@NotNull RequestStatus status){} @PatchMapping("/consultations/{id}") Map<String,Object> decide(Authentication a,@PathVariable UUID id,@RequestBody @Validated Decision i){return requestDto(service.decide(me(a),id,i.status));} @PatchMapping("/consultations/{id}/cancel") Map<String,Object> cancel(Authentication a,@PathVariable UUID id){return requestDto(service.cancel(me(a),id));} private Map<String,Object> assignmentDto(Assignment x){return Map.of("id",x.id,"title",x.title,"category",x.category,"dueDate",x.dueDate,"completed",x.completed);} private Map<String,Object> attendanceDto(AttendanceRecord x){int extra=service.additionalClasses(x.attendedClasses,x.totalClasses);return Map.of("id",x.id,"courseCode",x.courseCode,"courseName",x.courseName,"attended",x.attendedClasses,"total",x.totalClasses,"percentage",x.totalClasses==0?0:Math.round(x.attendedClasses*1000.0/x.totalClasses)/10.0,"additionalClassesRequired",extra);} private Map<String,Object> eventDto(AcademicEvent x){return Map.of("id",x.id,"title",x.title,"eventDate",x.eventDate,"category",x.category,"description",x.description,"demonstrationData",x.demonstrationData);} private Map<String,Object> resourceDto(Resource x){return Map.of("id",x.id,"title",x.title,"subject",x.subject,"resourceType",x.resourceType,"description",x.description,"externalUrl",x.externalUrl,"demonstrationData",x.demonstrationData);} private Map<String,Object> scheduleDto(ClassSchedule x){return Map.of("id",x.id,"courseCode",x.courseCode,"courseName",x.courseName,"weekday",x.weekday,"startTime",x.startTime,"endTime",x.endTime,"classroomCode",x.classroom==null?"":x.classroom.code);} private Map<String,Object> requestDto(ConsultationRequest r){return Map.of("id",r.id,"student",r.student.fullName,"faculty",r.faculty.fullName,"date",r.slot.slotDate,"startTime",r.slot.startTime,"status",r.status,"description",r.description);}
}
